import{_ as l,l as r,o as e,c as n,v as i,p as s,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"公共物品与免费搭车","description":"","frontmatter":{"title":"公共物品与免费搭车","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/public-goods.md","filePath":"econ/public-goods.md","lastUpdated":1789023840000}'),c={name:"econ/public-goods.md"};function E(m,a,u,B,A,_){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="公共物品与免费搭车" tabindex="-1">公共物品与免费搭车 <a class="header-anchor" href="#公共物品与免费搭车" aria-label="Permalink to &quot;公共物品与免费搭车&quot;">​</a></h1><div class="epigraph"><p>纯公共品的最优条件是边际替代率之和等于边际转换率；私人品则是各人 MRS 分别等于 MRT。</p><footer>—— Samuelson, The Pure Theory of Public Expenditure, Review of Economics and Statistics, 1954</footer></div><p><a href="/econ/cap-and-trade">上一课</a>（总量管制与许可证）。在两人、权利清晰、谈判免费时把外部性内部化。缺口是人数与消费技术：一种商品被一人消费并不减少另一人可消费的量，又很难把不付费者排除在外。此时「卖掉排放权」不再是双边交易，联盟会散。本课钉纯公共品的萨缪尔森条件与自愿供给的免费搭车，不写具体税种的归宿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>私人品在<a href="/econ/edgeworth-pareto">埃奇沃思盒</a>里总量守恒：你多一口，我少一口。公共品 \\(G\\) 进入每人的效用，但资源约束是 \\(c(G)+\\sum x^i=w\\)，不是 \\(\\sum G^i\\)。有效性的切条件因此从「MRS 相等」改成加总：</p> \\[\\sum_i \\mathrm{MRS}^i_{G,x} = \\mathrm{MRT}_{G,x}. \\]<p>左边是所有受益者的边际评价叠在同一单位 \\(G\\) 上。市场若按私人品定价，每人只显露自己的 MRS，加总偏小，均衡供给不足。</p><p>自愿贡献博弈里，别人多出一单位，自己的最优是少出——这就是免费搭车。科斯谈判在这里要召集所有受益者，阻塞联盟的规模等于全人口，核的逻辑帮不上小数目交易。</p><h3 id="非竞争不是非排他的同义词" tabindex="-1">非竞争不是非排他的同义词 <a class="header-anchor" href="#非竞争不是非排他的同义词" aria-label="Permalink to &quot;非竞争不是非排他的同义词&quot;">​</a></h3><p>非竞争（nonrival）说边际成本为零：多一人享用不必再生产。非排他（nonexcludable）说收不了费。灯塔、国防接近两者兼有；收费公路可以排他但仍接近非竞争。排他但非竞争的商品，Lindahl 定价在纸上可行：对人报个性化价格，使各人需求的 \\(G\\) 相同。执行要知道每人的 MRS，又回到显示问题。</p><p><span class="marginnote">Lindahl 均衡：每人面对价格 \\(p^i\\)，且 \\(\\sum_i p^i=\\mathrm{MC}(G)\\)，\\(G\\) 对所有人相同。它实现萨缪尔森条件，但 \\(p^i\\) 依赖偏好。谎报偏好可以压低 \\(p^i\\)，这是后课机制设计的伏笔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>纯公共品经济：私人品 \\(x^i\\)，公共品 \\(G\\)，技术 \\(c(G)\\)。帕累托最优由一个计划者在资源约束下最大化一人效用、其余维持保留水平，一阶条件即萨缪尔森加总。分散化：若能征个性化 Lindahl 价，并配合总额转移，第二定理的逻辑仍可用。做不到个性化价时，统一税融资加公共提供，是用一种工具同时做供给与分担。</p><p>自愿供给：效用 \\(u^i(x^i,G)\\)，\\(G=\\sum_j g^j\\)。纳什贡献的一阶条件是各人自己的 MRS 等于私人品的机会成本，加总远小于 MRT。人数上升，每人贡献更接近零。Olson 强调小集团更容易组织，与科斯小数目一致。</p>',14)),(e(),s(h,null,{default:o(()=>[d(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIV%5B%22%E7%A7%81%E4%BA%BA%E5%93%81%EF%BC%9AMRS%20%E5%88%86%E5%88%AB%20%3D%20MRT%22%5D%20--%3E%20PUB%5B%22%E5%85%AC%E5%85%B1%E5%93%81%EF%BC%9A%CE%A3%20MRS%20%3D%20MRT%22%5D%0A%20%20PUB%20--%3E%20VOL%5B%22%E8%87%AA%E6%84%BF%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%8F%AA%E5%AF%B9%E9%BD%90%E8%87%AA%E5%B7%B1%E7%9A%84%20MRS%22%5D%0A%20%20VOL%20--%3E%20FR%5B%22%E5%85%8D%E8%B4%B9%E6%90%AD%E8%BD%A6%EF%BC%8C%E4%BE%9B%E7%BB%99%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20PUB%20--%3E%20LIN%5B%22Lindahl%20%E4%BB%B7%EF%BC%9A%E8%A6%81%E7%9C%9F%E5%AE%9E%E5%81%8F%E5%A5%BD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>本课不引入投票、中位选民；那些是政治机制，不是商品空间补全。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么必须加总 MRS：一单位 \\(G\\) 同时进入所有人的效用，社会边际收益是竖着加，不是横着比。私人品的市场把横比做成同一价格；公共品没有「每人买自己的那一份」，价格无法按人分开，除非人为做成 Lindahl 价。</p><p>免费搭车是占优或纳什意义下的激励，不是道德批评。即使所有人都珍视 \\(G\\)，策略仍是让别人出钱。这与<a href="/econ/externality-pigou">庇古</a>的正外部性是同一缺口的极端：受益者太多，补贴该发给谁，信息与免费搭车缠在一起。</p><h3 id="竖加总与横加总" tabindex="-1">竖加总与横加总 <a class="header-anchor" href="#竖加总与横加总" aria-label="Permalink to &quot;竖加总与横加总&quot;">​</a></h3><p>私人品市场把个人需求曲线横着加（同一价格、数量相加）。公共品若硬用同一个价格，每人只按自己的 MRS 买，加总数量对不上社会竖着加起来的收益。Lindahl 把价格按人拆开，等于竖加：每人一条需求，数量必须同为 \\(G\\)，价格不同。执行要知道那条个性化需求，谎报可以压低自己的 \\(p^i\\)、仍享受同一 \\(G\\)——显示问题比庇古税更重，因为税至少可以对着可观察的排放，MRS 不可观察。</p><p>俱乐部物品可排他、容量内非竞争，会费加拥挤税是另一套；本课极点是既不能排他又非竞争。拥挤一起，有效条件要加拥挤的 MD，退回外部性语言。</p><p><span class="marginnote">自愿贡献的纳什均衡在人数 \\(n\\to\\infty\\) 时，人均贡献趋于零，\\(G\\) 可以停在有限或缓慢上升，取决于偏好是否把 \\(G\\) 当正常品。Olson 的小集团是 \\(n\\) 小、贡献可互相看见的对照。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>萨缪尔森条件是完全信息计划者的一阶条件，不保证能显示。后课<a href="/econ/revelation-principle">显示原理</a>会处理「问偏好」本身的激励。拥挤使非竞争只在容量内成立，有效条件要加拥挤税。地方公共品、Tiebout 用脚投票，不在本课。</p><p>也不要把公共品写成「政府必须生产」。可以公共融资、私人生产。本课只钉配置条件与自愿供给失败。下一课问：用来融资的税，法定纳税人是不是实际负担者。</p><p>后课默认：纯公共品的效率标尺是 \\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\)；市场自愿供给达不到。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非竞争使有效条件从 MRS 相等变成 MRS 之和。</li><li>自愿贡献只对齐私人 MRS，人数一多就免费搭车。</li><li>Lindahl 价能分权，但要真实的个性化评价。</li><li>科斯谈判在全人口联盟上失效。</li><li>出处：Samuelson, <em>REStat</em> 1954；Olson, <em>The Logic of Collective Action</em>, 1965。</li></ul>',14))])}const R=l(c,[["render",E]]);export{f as __pageData,R as default};
